import{z as s,x as l,o as t,c as p,q as i,j as n,D as E,d as A,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"AGV 期望外部性","description":"","frontmatter":{"title":"AGV 期望外部性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/agv-mechanism.md","filePath":"econ/agv-mechanism.md","lastUpdated":1791063341000}'),d={name:"econ/agv-mechanism.md"};function h(m,a,C,_,c,D){const r=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="agv-期望外部性" tabindex="-1">AGV 期望外部性 <a class="header-anchor" href="#agv-期望外部性" aria-label="Permalink to &quot;AGV 期望外部性&quot;">​</a></h1><div class="epigraph"><p>每人支付自己对他人期望福利造成的外部性，则有效配置在贝叶斯激励相容下可实施，且转移可以事后预算平衡。</p><footer>—— d&#39;Aspremont and Gérard-Varet, Incentives and Incomplete Information, Journal of Public Economics, 1979；Arrow, The Property Rights Doctrine and Demand Revelation under Incomplete Information, 1979</footer></div><p><a href="/econ/myerson-satterthwaite">上一课</a>证明：事后有效、事中 IR、IC 与预算平衡不能一起要。缺口是：若放弃事中自愿参与，能否保住有效与平衡？AGV（期望外部性）给出肯定：转移不按枢轴的事后实现来收，而按「对他人类型取期望」的外部性来收。本课钉这条机制，不把无转移的匹配写成拍卖，也不重推 MS 的包络亏空。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公共品或双边交易，有效规则 \\(x^*(\\theta)=\\arg\\max_x\\sum_i v_i(x,\\theta_i)\\)。VCG / 克拉克枢轴：每人付自己给别人造成的<strong>事后</strong>福利差，占优策略 IC，但转移一般不平衡（设计者赤字）。AGV：给 \\(i\\) 的转移是</p> \\[t_i(\\hat\\theta_i)= \\mathbb{E}_{\\theta_{-i}}\\Bigl[\\sum_{j\\neq i} v_j\\bigl(x^*(\\hat\\theta_i,\\theta_{-i}),\\theta_j\\bigr)\\Bigr] + h_i(\\hat\\theta_{-i}), \\]<p>即 \\(i\\) 的报告通过 \\(x^*\\) 加在别人身上的<strong>期望</strong>外部性（外加只依赖别人报告的 \\(h_i\\)）。选 \\(h\\) 可使 \\(\\sum t_i=0\\) 对每一报告向量成立（事后预算平衡）。</p><p>贝叶斯 IC：在共同先验下，报真值最大化期望支付。不是占优策略——先验错了，IC 会坏。</p><p><span class="marginnote">术语翻译：期望外部性就是「你对别人福利的影响，按类型分布取平均后记在你账上」。你谎报类型会改变有效配置，从而改变别人的期望福利；AGV 让这笔变化由你的转移支付承担，于是谎报等于给自己加账，说真话成了最优。</span></p><h3 id="不与-ms-矛盾" tabindex="-1">不与 MS 矛盾 <a class="header-anchor" href="#不与-ms-矛盾" aria-label="Permalink to &quot;不与 MS 矛盾&quot;">​</a></h3><p>MS 要事中 IR。AGV 的期望支付对某些类型可以为负：高成本卖家、低估值买家可能「被有效规则强迫参加」，事中宁愿退出。事前 IR（对类型取期望后再比不参与）有时能满足，事中不能——这正是上一课缺口里被放松的那一条。</p><p><span class="marginnote">Arrow 与 d&#39;Aspremont–Gérard-Varet 独立给出期望外部性。课堂上 AGV 常对照 Groves：一个对每个 \\(v_{-i}\\) 都内部化（占优），一个只对分布内部化（贝叶斯）。平衡性来自「期望」把交叉项收成可抵消的 \\(h_i\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：准线性、共同先验、有限或紧类型空间。先取有效 \\(x^*\\)，再写期望 Groves 项，最后解 \\(h_i\\) 使预算恒等为零（若期望外部性之和已能写成可分离形式）。检验：偏离报告等于在错误的边际上最大化「自己的价值 + 别人的期望价值」，而真值才对齐社会目标的期望。</p>',14)),(t(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MS%5B%22MS%EF%BC%9A%E5%9B%9B%E8%80%85%E4%B8%8D%E5%8F%AF%E5%85%BC%E5%BE%97%22%5D%20--%3E%20DROP%5B%22%E6%94%BE%E5%BC%83%E4%BA%8B%E4%B8%AD%20IR%22%5D%0A%20%20DROP%20--%3E%20AGV%5B%22%E6%9C%9F%E6%9C%9B%E5%A4%96%E9%83%A8%E6%80%A7%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20AGV%20--%3E%20BIC%5B%22%E8%B4%9D%E5%8F%B6%E6%96%AF%20IC%20%2B%20%E6%9C%89%E6%95%88%22%5D%0A%20%20AGV%20--%3E%20BB%5B%22%E5%8F%AF%E4%BA%8B%E5%90%8E%E9%A2%84%E7%AE%97%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20VCG%5B%22VCG%EF%BC%9A%E5%8D%A0%E4%BC%98%20IC%22%5D%20--%3E%20DEF%5B%22%E4%B8%80%E8%88%AC%E9%A2%84%E7%AE%97%E8%B5%A4%E5%AD%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"公共品、双边交易、团队生产，只要有效规则明确、先验共同，同一套转移。匹配下一课开始没有货币，\\(t\\) 写不出，AGV 用不上。双边交易教具：有效规则是 \\(v\\ge c\\) 则成交，期望外部性让买家承担「自己的报告如何改变卖方的期望剩余」，预算用 \\(h\\) 对冲；低 \\(v\\)、高 \\(c\\) 的类型事中可能为负，正是 MS 卡住的那些端点。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"占优策略要求对每一对手报告都内部化，转移被钉得太死，加总留赤字。贝叶斯只要求对先验平均内部化，设计者多出一组 \\(h_i(\\theta_{-i})\\) 的自由度，正好用来平衡预算。代价是执行依赖「大家都按这个先验算期望」；先验不是共同知识时，AGV 的 IC 比 VCG 脆。",-1)),(t(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20REP%5B%22%E4%BD%A0%E6%8A%A5%E5%91%8A%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20X%5B%22%E6%9C%89%E6%95%88%E8%A7%84%E5%88%99%E5%AE%9A%E5%87%BA%E9%85%8D%E7%BD%AE%20x%20%E6%98%9F%22%5D%0A%20%20X%20--%3E%20OTHER%5B%22%E5%88%AB%E4%BA%BA%E4%BB%8E%E9%85%8D%E7%BD%AE%E9%87%8C%E5%BE%97%E5%88%B0%E7%9A%84%E7%A6%8F%E5%88%A9%E5%8F%98%E5%8C%96%22%5D%0A%20%20OTHER%20--%3E%20PAY%5B%22%E8%BF%99%E4%B8%AA%E5%8F%98%E5%8C%96%E7%9A%84%E6%9C%9F%E6%9C%9B%E8%AE%B0%E5%9C%A8%E4%BD%A0%E7%9A%84%E8%BD%AC%E7%A7%BB%E4%B8%8A%22%5D%0A%20%20PAY%20--%3E%20LIE%5B%22%E8%B0%8E%E6%8A%A5%E4%BC%9A%E6%94%B9%E5%8F%98%E9%85%8D%E7%BD%AE%E5%B9%B6%E7%BB%99%E8%87%AA%E5%B7%B1%E5%8A%A0%E8%B4%A6%22%5D%0A%20%20LIE%20--%3E%20TRUE%5B%22%E8%AF%B4%E7%9C%9F%E8%AF%9D%E6%98%AF%E6%9C%9F%E6%9C%9B%E6%9C%80%E4%BC%98%3A%20%E8%B4%9D%E5%8F%B6%E6%96%AF%20IC%22%5D%0A%20%20H%5B%22h_i%20%E9%A1%B9%3A%20%E5%8F%AA%E4%BE%9D%E8%B5%96%E5%88%AB%E4%BA%BA%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20NET%5B%22%E5%90%84%E9%A1%B9%E5%8A%A0%E6%80%BB%E4%B8%BA%E9%9B%B6%3A%20%E9%A2%84%E7%AE%97%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20PAY%20--%3E%20NET%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>事中 IR 失败的几何：有效规则会让「不该交易」的报告组合仍按期望外部性付钱——极端类型承担了为别人的效率付账。MS 把这些人的事中支付托在保留效用之上，于是预算裂开。AGV 不托，预算能合上。</p><p><span class="marginnote">直觉类比：VCG 像拍卖行每场都自己倒贴奖励，激励对了但账本永远亏；AGV 像 club 内部转账——每个人交的账最终都在成员之间流转，左手收右手，总账合得上。换来这一点的是：所有人都得认同一张「类型分布地图」（共同先验）。</span></p><p><span class="marginnote">常见误区：初学者容易把贝叶斯 IC 当成占优 IC 的弱化版、照样放心用。差别是实质的：占优 IC 下说真话不依赖别人怎么想；贝叶斯 IC 的真话策略建立在「大家共享同一先验」之上。先验稍偏或互不信任，说真话就可能不再是均衡。</span></p><h3 id="团队与公共品是同一会计" tabindex="-1">团队与公共品是同一会计 <a class="header-anchor" href="#团队与公共品是同一会计" aria-label="Permalink to &quot;团队与公共品是同一会计&quot;">​</a></h3><p>团队里每人报边际产出，AGV 让每人承担对其余产出期望的影响，平衡时总奖金不靠老板贴钱。公共品里每人报 MRS，期望林达尔式转移可平衡，但低需求类型可能事中亏损——与「自愿贡献不足」不同：这里是强制规则加转移，不是纳什自愿供给。</p><p><span class="marginnote">若坚持占优策略 IC 又要平衡，一般只剩下无弹性的机制（Green–Laffont）。贝叶斯是换来平衡与有效的那一层。后课 Gale–Shapley 连转移都没有，解概念改成稳定，不再用 \\(t_i\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>相关类型、没有共同先验、风险厌恶，期望外部性不必 IC。动态、重新谈判会把 \\(h_i\\) 的承诺掀掉。也不要把 AGV 写成宏观转移支付或限价簿手续费。</p><p>后课默认：放松事中 IR 之后，有效 + 贝叶斯 IC + 预算平衡可用 AGV 实施。下一课进入无货币的双边匹配：稳定配对，不再靠转移内部化外部性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MS 卡住是因为事中 IR；AGV 放弃它，保住有效与平衡。</li><li>转移按对他人的期望外部性来收，IC 是贝叶斯的，不是占优。</li><li>VCG 更强的 IC，一般不平衡；AGV 相反。</li><li>没有共同先验或没有货币时，这套转移写不出。</li><li>出处：d&#39;Aspremont and Gérard-Varet, <em>JPubE</em>, 1979；Arrow, 1979。</li></ul>',11))])}const I=s(d,[["render",h]]);export{u as __pageData,I as default};
